Destrucción aleatoria de clientes. Libera todos los arcos que entran o salen de los clientes elegidos. Con cierta probabilidad también libera los de sus vecinos de ruta, para que el sub-MIP pueda reconectar esas rutas.

```python
from random import Random

COMPONENT = {
    "name": "random_customer_arc_destruction",
    "slot": "destruction",
    "compatible_skeletons": ["LNS_MIP", "MIP_PERTURB"],
    "requires": ["ProblemModel.to_assignment"],
    "params": {
        "neighbor_prob": {"type": "float", "range": [0.0, 1.0]},
    },
}


class RandomCustomerArcDestruction:
    """Elige clientes al azar y libera todos los arcos x_i_j incidentes a ellos
    (y, con probabilidad neighbor_prob, también los de su predecesor/sucesor)."""

    def __init__(self, problem, inst, neighbor_prob):
        self.problem = problem
        self.inst = inst
        self.neighbor_prob = float(neighbor_prob)

    def _neighbors(self, sol):
        pred, succ = {}, {}
        for r in sol:
            nodes = [int(c) for c in r]
            for k, c in enumerate(nodes):
                pred[c] = nodes[k - 1] if k > 0 else 0
                succ[c] = nodes[k + 1] if k + 1 < len(nodes) else 0
        return pred, succ

    def _free_arcs(self, nodes, assignment):
        N = self.inst.n_customers + 1
        free = set()
        for t in nodes:
            for k in range(N):
                if k == t:
                    continue
                a = f"x_{t}_{k}"
                b = f"x_{k}_{t}"
                if a in assignment:
                    free.add(a)
                if b in assignment:
                    free.add(b)
        return free

    def destroy(self, sol, ratio: float, rng: Random):
        assignment = self.problem.to_assignment(sol)
        custs = list(self.inst.customers)
        n = len(custs)
        if n == 0 or not assignment:
            keys = sorted(assignment)
            free = {keys[0]} if keys else set()
            return {v: x for v, x in assignment.items() if v not in free}, free
        k = max(1, min(n, int(round(ratio * n))))
        chosen = set(rng.sample(custs, k))
        pred, succ = self._neighbors(sol)
        extra = set()
        for c in chosen:
            if rng.random() < self.neighbor_prob:
                p = pred.get(c, 0)
                s = succ.get(c, 0)
                if p != 0:
                    extra.add(p)
                if s != 0:
                    extra.add(s)
        nodes = chosen | extra
        free_vars = self._free_arcs(nodes, assignment)
        if not free_vars:
            free_vars = {sorted(assignment)[0]}
        partial = {v: x for v, x in assignment.items() if v not in free_vars}
        return partial, free_vars


def build_component(problem, neighbor_prob=0.5):
    return RandomCustomerArcDestruction(problem, problem.inst, neighbor_prob)
```

Destrucción por relación (Shaw). Elige clientes parecidos a los ya elegidos, según cercanía espacial, pertenencia a la misma ruta y demanda similar. La selección es aleatoria pero sesgada.

```python
from random import Random

COMPONENT = {
    "name": "shaw_relatedness_arc_destruction",
    "slot": "destruction",
    "compatible_skeletons": ["LNS_MIP", "MIP_PERTURB"],
    "requires": ["ProblemModel.to_assignment"],
    "params": {
        "determinism": {"type": "float", "range": [1.0, 12.0]},
        "route_weight": {"type": "float", "range": [0.0, 1.0]},
        "demand_weight": {"type": "float", "range": [0.0, 1.0]},
    },
}


class ShawRelatednessArcDestruction:
    """Remoción tipo Shaw: semilla aleatoria y luego clientes con alta relación
    (distancia normalizada + misma ruta + demanda similar) a alguno ya removido.
    Libera todos los arcos incidentes a los clientes removidos."""

    def __init__(self, problem, inst, determinism, route_weight, demand_weight):
        self.problem = problem
        self.inst = inst
        self.p = float(determinism)
        self.rw = float(route_weight)
        self.dw = float(demand_weight)
        custs = list(inst.customers)
        maxd = 0.0
        for a in [0] + custs:
            for b in custs:
                if a != b:
                    d = inst.dist(a, b)
                    if d > maxd:
                        maxd = d
        self.maxd = maxd if maxd > 0 else 1.0
        dem = [inst.demand[c] for c in custs] or [0.0]
        span = max(dem) - min(dem)
        self.dspan = span if span > 0 else 1.0

    def _free_arcs(self, nodes, assignment):
        N = self.inst.n_customers + 1
        free = set()
        for t in nodes:
            for k in range(N):
                if k == t:
                    continue
                a = f"x_{t}_{k}"
                b = f"x_{k}_{t}"
                if a in assignment:
                    free.add(a)
                if b in assignment:
                    free.add(b)
        return free

    def destroy(self, sol, ratio: float, rng: Random):
        inst = self.inst
        assignment = self.problem.to_assignment(sol)
        custs = list(inst.customers)
        n = len(custs)
        if n == 0 or not assignment:
            keys = sorted(assignment)
            free = {keys[0]} if keys else set()
            return {v: x for v, x in assignment.items() if v not in free}, free
        k = max(1, min(n, int(round(ratio * n))))
        route_of = {}
        for idx, r in enumerate(sol):
            for c in r:
                route_of[int(c)] = idx

        def rel(a, b):
            v = inst.dist(a, b) / self.maxd
            if route_of.get(a, -1) != route_of.get(b, -2):
                v += self.rw
            v += self.dw * abs(inst.demand[a] - inst.demand[b]) / self.dspan
            return v

        removed = [rng.choice(custs)]
        removed_set = set(removed)
        while len(removed) < k:
            ref = rng.choice(removed)
            rest = [c for c in custs if c not in removed_set]
            if not rest:
                break
            rest.sort(key=lambda c: (rel(ref, c), c))
            y = rng.random()
            pos = int((y ** self.p) * len(rest))
            pos = min(pos, len(rest) - 1)
            c = rest[pos]
            removed.append(c)
            removed_set.add(c)
        free_vars = self._free_arcs(removed_set, assignment)
        if not free_vars:
            free_vars = {sorted(assignment)[0]}
        partial = {v: x for v, x in assignment.items() if v not in free_vars}
        return partial, free_vars


def build_component(problem, determinism=5.0, route_weight=0.3, demand_weight=0.1):
    return ShawRelatednessArcDestruction(problem, problem.inst, determinism,
                                         route_weight, demand_weight)
```

Destrucción por rutas completas vecinas. Libera una ruta semilla y las rutas con centroide más cercano, para que el sub-MIP pueda reorganizar, fusionar o partir rutas en esa zona.

```python
import math
from random import Random

COMPONENT = {
    "name": "route_cluster_arc_destruction",
    "slot": "destruction",
    "compatible_skeletons": ["LNS_MIP", "MIP_PERTURB"],
    "requires": ["ProblemModel.to_assignment"],
    "params": {
        "partial_last": {"type": "bool"},
        "seed_mode": {"type": "cat", "values": ["random", "worst_avg_cost"]},
    },
}


class RouteClusterArcDestruction:
    """Selecciona una ruta semilla (al azar o la de mayor costo por cliente) y añade
    rutas enteras ordenadas por cercanía de centroides hasta cubrir ~ratio·n clientes.
    Libera todos los arcos incidentes a los clientes de esas rutas."""

    def __init__(self, problem, inst, partial_last, seed_mode):
        self.problem = problem
        self.inst = inst
        self.partial_last = bool(partial_last)
        self.seed_mode = seed_mode

    def _free_arcs(self, nodes, assignment):
        N = self.inst.n_customers + 1
        free = set()
        for t in nodes:
            for k in range(N):
                if k == t:
                    continue
                a = f"x_{t}_{k}"
                b = f"x_{k}_{t}"
                if a in assignment:
                    free.add(a)
                if b in assignment:
                    free.add(b)
        return free

    def _centroid(self, r):
        xs = [self.inst.coords[c][0] for c in r]
        ys = [self.inst.coords[c][1] for c in r]
        return (sum(xs) / len(xs), sum(ys) / len(ys))

    def _route_cost(self, r):
        prev, tot = 0, 0.0
        for c in r:
            tot += self.inst.dist(prev, c)
            prev = c
        return tot + self.inst.dist(prev, 0)

    def destroy(self, sol, ratio: float, rng: Random):
        inst = self.inst
        assignment = self.problem.to_assignment(sol)
        n = inst.n_customers
        routes = [tuple(int(c) for c in r if 1 <= int(c) <= n) for r in sol]
        routes = [r for r in routes if r]
        if n == 0 or not routes or not assignment:
            keys = sorted(assignment)
            free = {keys[0]} if keys else set()
            return {v: x for v, x in assignment.items() if v not in free}, free
        k = max(1, min(n, int(round(ratio * n))))
        if self.seed_mode == "worst_avg_cost":
            scored = sorted(range(len(routes)),
                            key=lambda i: -self._route_cost(routes[i]) / len(routes[i]))
            top = scored[:max(1, min(3, len(scored)))]
            seed = rng.choice(top)
        else:
            seed = rng.randrange(len(routes))
        cs = self._centroid(routes[seed])
        others = [i for i in range(len(routes)) if i != seed]
        others.sort(key=lambda i: (math.hypot(self._centroid(routes[i])[0] - cs[0],
                                              self._centroid(routes[i])[1] - cs[1]),
                                   rng.random()))
        removed = set(routes[seed])
        for i in others:
            if len(removed) >= k:
                break
            r = routes[i]
            if self.partial_last and len(removed) + len(r) > k:
                need = k - len(removed)
                part = sorted(r, key=lambda c: (math.hypot(inst.coords[c][0] - cs[0],
                                                           inst.coords[c][1] - cs[1]), c))
                removed.update(part[:need])
                break
            removed.update(r)
        # Rutas no listadas (p.ej. clientes ausentes en sol) se ignoran; se garantiza >=1 libre.
        free_vars = self._free_arcs(removed, assignment)
        if not free_vars:
            free_vars = {sorted(assignment)[0]}
        partial = {v: x for v, x in assignment.items() if v not in free_vars}
        return partial, free_vars


def build_component(problem, partial_last=True, seed_mode="random"):
    return RouteClusterArcDestruction(problem, problem.inst, partial_last, seed_mode)
